pub fn copy(arr: &Vec<i8>) -> Vec<i8> {
    // `to_vec()` clones all elements, producing an exact copy with the same length.
    arr.to_vec()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn copies_empty() {
        let a: Vec<i8> = vec![];
        let b = copy(&a);
        assert_eq!(b, a);
        assert_eq!(b.len(), a.len());
    }

    #[test]
    fn copies_values() {
        let a: Vec<i8> = vec![-128, -1, 0, 1, 127];
        let b = copy(&a);
        assert_eq!(b, a);
        assert_eq!(b.len(), a.len());
    }

    #[test]
    fn copy_is_independent() {
        let a: Vec<i8> = vec![1, 2, 3];
        let mut b = copy(&a);
        b[0] = 9;
        assert_eq!(a, vec![1, 2, 3]);
        assert_eq!(b, vec![9, 2, 3]);
    }
}